      "file": "d27.js",
      "line": 5,
      "evidence": "fetch() call lacks an AbortSignal",
      "llm_reasoning": "Without a timeout, a hanging network request can block the event loop indefinitely, leading to resource exhaustion.",
      "suggested_fix": "Use AbortController to implement a timeout for each fetch request."
